namespace ZakoChat
{
    internal static class WebSafeTemplates
    {
        public static string BuildQuickHtml()
        {
            return @"<!doctype html><html><head><meta charset='utf-8'><style>" + SharedCss + QuickCss + @"</style></head><body><main class='quick-shell' id='drag'><header><div class='brand'><span class='zako-mark'></span><div><b id='app'>Zako Chat</b><small id='status'></small></div></div><nav><button title='&#23637;&#24320;&#20391;&#26639;' data-action='expand'>" + UiIcons.Expand + @"</button><button title='&#35774;&#32622;' data-action='settings'>" + UiIcons.Settings + @"</button><button title='&#38544;&#34255;' data-action='hide'>" + UiIcons.Close + @"</button></nav></header><section class='composer'><textarea id='input' placeholder='&#21521; Zako &#25552;&#38382;...'></textarea><button class='send' id='send' title='&#21457;&#36865;'>" + UiIcons.Send + @"</button></section></main><script>" + QuickScript + @"</script></body></html>";
        }

        public static string BuildSidebarHtml()
        {
            return @"<!doctype html><html><head><meta charset='utf-8'><style>" + SharedCss + SidebarCss + @"</style></head><body><div class='app'><aside><div class='side-title'><span class='zako-mark small'></span><div><b>Zako</b><small>&#21382;&#21490;&#35760;&#24405;</small></div></div><button class='new' id='newChat'>" + UiIcons.Add + @"<span>&#26032;&#24314;&#23545;&#35805;</span></button><div class='sessions' id='sessions'></div></aside><main><header><div class='head-copy'><h1 id='appName'>Zako Chat</h1><p id='status'></p></div><div class='mode-switch'><button id='modeText' class='active'>&#25991;&#23383;&#23545;&#35805;</button><button id='modeImage'>&#22270;&#29255;&#29983;&#25104;</button></div><div class='tools'><button id='toggleEdge' class='tool-wide' title='&#20999;&#25442;&#24038;&#21491;&#20391;'>" + UiIcons.Side + @"<span>&#24038;&#21491;</span></button><button id='settings' class='tool-wide' title='&#35774;&#32622;'>" + UiIcons.Settings + @"<span>&#35774;&#32622;</span></button><button id='quickClose' title='&#38544;&#34255;&#21040;&#25176;&#30424;'>" + UiIcons.Close + @"</button></div></header><section class='messages' id='messages'></section><footer><div class='attachment' id='attachment'></div><textarea id='input' placeholder='&#36755;&#20837;&#28040;&#24687;&#65292;Ctrl+Enter &#21457;&#36865;'></textarea><button id='upload' title='&#19978;&#20256;&#22270;&#29255;&#32473;&#35270;&#35273;&#27169;&#22411;'>" + UiIcons.Image + @"</button><button id='send' class='send' title='&#21457;&#36865;'>" + UiIcons.Send + @"</button></footer></main></div><script>" + SidebarScript + @"</script></body></html>";
        }

        private const string SharedCss = @":root{--accent:#2563eb;--accentText:#fff;--text:#1f2328;--sub:#5f6673;--muted:#8a92a3;--windowTop:#f8fbff;--windowBottom:#eef3fb;--glass:rgba(255,255,255,.80);--glass2:rgba(255,255,255,.58);--line:rgba(0,0,0,.10);--hover:rgba(0,0,0,.055);--press:rgba(0,0,0,.09);--shadow:rgba(0,0,0,.20);--prompt:rgba(255,255,255,.94);--danger:#d13438}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden}body{font-family:'Segoe UI Variable Text','Segoe UI Variable','Segoe UI','Microsoft YaHei UI',sans-serif;color:var(--text);background:var(--windowBottom)}body[data-theme='dark']{--glass:rgba(42,45,54,.92);--glass2:rgba(34,37,45,.80);--line:rgba(255,255,255,.12);--hover:rgba(255,255,255,.09);--press:rgba(255,255,255,.14);--shadow:rgba(0,0,0,.46);--prompt:rgba(48,51,60,.96);--danger:#ff8a8a}button,textarea{font:inherit}button{border:0;color:var(--text);cursor:pointer;background:transparent}.ui-icon{width:20px;height:20px;display:block;overflow:visible;flex:0 0 auto}button .ui-icon{margin:auto}.zako-mark{width:30px;height:30px;border-radius:12px;background:conic-gradient(from 215deg,var(--accent),#72f0cf,#8aa8ff,var(--accent));box-shadow:inset 0 1px 0 rgba(255,255,255,.65),0 0 24px rgba(90,160,255,.24)}.zako-mark.small{width:26px;height:26px;border-radius:10px}nav button,.tools button{height:40px;display:grid;place-items:center;border-radius:13px;border:1px solid transparent;transition:background .12s ease,border-color .12s ease,transform .12s ease}nav button{width:40px}.tools button{width:40px}.tools .tool-wide{width:72px;grid-template-columns:20px 1fr;gap:6px;padding:0 9px}.tools .tool-wide span{font-size:12px;color:var(--sub);line-height:1;white-space:nowrap}nav button:hover,.tools button:hover{background:var(--hover);border-color:var(--line)}nav button:active,.tools button:active{background:var(--press);transform:scale(.97)}textarea{resize:none;outline:none;color:var(--text);background:transparent;border:0}textarea::placeholder{color:var(--muted)}";

        private const string QuickCss = @".quick-shell{width:100vw;height:100vh;padding:13px 14px 14px;border:1px solid var(--line);border-radius:28px;background:linear-gradient(145deg,var(--glass),var(--glass2));box-shadow:inset 0 1px 0 rgba(255,255,255,.2),0 20px 46px var(--shadow);backdrop-filter:blur(30px) saturate(150%)}header{height:38px;display:flex;align-items:center;justify-content:space-between;user-select:none}header,.brand{display:flex;align-items:center;gap:11px}.brand b{display:block;font-size:14px;font-weight:650}.brand small{display:block;max-width:480px;font-size:11px;color:var(--sub);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}nav{display:flex;gap:6px}.composer{height:76px;margin-top:10px;padding:12px 12px 12px 16px;border-radius:24px;background:var(--prompt);border:1px solid var(--line);display:grid;grid-template-columns:1fr 40px;gap:12px;box-shadow:inset 0 1px 0 rgba(255,255,255,.18)}.composer:focus-within{border-color:var(--accent);box-shadow:0 0 0 3px rgba(96,165,250,.16),inset 0 1px 0 rgba(255,255,255,.18)}#input{height:50px;line-height:25px;font-size:15px}.send{width:40px;height:40px;border-radius:15px;align-self:end;display:grid;place-items:center;background:var(--accent);color:var(--accentText);box-shadow:0 8px 22px rgba(70,120,240,.22);transition:transform .12s ease,filter .12s ease}.send:hover{filter:brightness(1.06)}.send:active{transform:scale(.96)}.send:disabled{opacity:.5}";

        private const string SidebarCss = @".app{width:100vw;height:100vh;display:grid;grid-template-columns:214px minmax(0,1fr);background:linear-gradient(145deg,var(--windowTop),var(--windowBottom));border:1px solid var(--line);border-radius:24px;overflow:hidden;box-shadow:inset 0 1px 0 rgba(255,255,255,.16),0 16px 42px var(--shadow)}aside{min-width:0;padding:16px 10px;border-right:1px solid var(--line);background:var(--glass2);backdrop-filter:blur(24px) saturate(140%)}.side-title{height:38px;display:flex;align-items:center;gap:10px;margin:0 6px 12px}.side-title b{font-size:14px}.side-title small{display:block;color:var(--sub);font-size:11px}.new{width:100%;height:42px;border-radius:13px;background:var(--hover);display:grid;grid-template-columns:20px 1fr;align-items:center;gap:10px;padding:0 12px;border:1px solid var(--line);text-align:left}.new span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.new:hover{background:var(--press)}.sessions{margin-top:12px;height:calc(100% - 70px);overflow:auto;padding-right:2px}.session{position:relative;width:100%;min-height:50px;margin:4px 0;padding:8px 40px 8px 10px;border-radius:13px;color:var(--sub);cursor:pointer;transition:background .12s ease,color .12s ease}.session:hover{background:var(--hover);color:var(--text)}.session.active{background:rgba(96,165,250,.18);color:var(--text)}.session b{display:block;font-size:12px;font-weight:520;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.session small{font-size:10px;color:var(--muted)}.del{position:absolute;right:6px;top:8px;width:32px;height:32px;display:grid;place-items:center;border-radius:10px;opacity:0}.session:hover .del{opacity:1}.del:hover{background:var(--press);color:var(--danger)}main{min-width:0;display:grid;grid-template-rows:106px minmax(0,1fr) auto}header{min-width:0;padding:10px 16px 9px;display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-rows:40px 38px;gap:8px 12px;align-items:center;border-bottom:1px solid var(--line);background:var(--glass)}.head-copy{min-width:0;grid-column:1;grid-row:1}h1{margin:0;font-size:18px;font-weight:650}p{margin:3px 0 0;color:var(--sub);font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.mode-switch{grid-column:1 / 3;grid-row:2;height:38px;padding:3px;display:flex;justify-self:center;gap:3px;border:1px solid var(--line);border-radius:15px;background:var(--hover)}.mode-switch button{height:30px;min-width:92px;padding:0 14px;border-radius:12px;font-size:12px;color:var(--sub)}.mode-switch button.active{background:var(--prompt);color:var(--text);box-shadow:0 1px 8px rgba(0,0,0,.08)}.tools{grid-column:2;grid-row:1;display:flex;gap:6px;align-items:center}.close-fast:hover{color:var(--danger)}.messages{min-height:0;padding:18px;overflow:auto;background:rgba(0,0,0,.018);overflow-anchor:none}body[data-theme='dark'] .messages{background:rgba(0,0,0,.08)}.msg{max-width:92%;margin:0 0 12px;padding:12px 14px;border-radius:18px;line-height:1.55;font-size:13.5px;white-space:pre-wrap;word-break:break-word;border:1px solid var(--line);box-shadow:inset 0 1px 0 rgba(255,255,255,.08)}.msg.user{margin-left:auto;background:var(--accent);color:var(--accentText);border-color:transparent}.msg.assistant{background:var(--prompt)}.image-card,.vision-card{white-space:normal}.image-card img,.vision-card img{display:block;max-width:100%;max-height:380px;border-radius:14px;margin-top:10px;border:1px solid var(--line);object-fit:contain;background:#111}.image-meta,.attach-meta{margin-top:8px;font-size:11px;color:var(--muted)}.msg.user .attach-meta{color:rgba(255,255,255,.78)}.empty{height:100%;display:grid;place-items:center;color:var(--muted);text-align:center}footer{position:relative;padding:14px 18px;background:var(--glass);border-top:1px solid var(--line);display:grid;grid-template-columns:minmax(0,1fr) 42px 46px;grid-template-rows:auto 94px;gap:10px}.attachment{grid-column:1 / -1;min-height:0}.attachment:not(:empty){margin-bottom:2px}.attach-chip{display:flex;align-items:center;gap:8px;width:max-content;max-width:100%;padding:6px 8px;border:1px solid var(--line);border-radius:12px;background:var(--prompt);font-size:12px;color:var(--sub)}.attach-chip b{max-width:360px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--text);font-weight:520}.attach-chip button{width:26px;height:26px;border-radius:9px;display:grid;place-items:center;background:var(--hover)}footer textarea{grid-column:1;grid-row:2;height:94px;min-width:0;padding:13px 14px;border-radius:19px;background:var(--prompt);border:1px solid var(--line);line-height:1.5}footer textarea:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(96,165,250,.16)}footer>button{grid-row:2;width:42px;height:42px;align-self:end;border-radius:15px;background:var(--hover);display:grid;place-items:center}footer>button:hover{background:var(--press)}footer .send{width:46px;height:46px;border-radius:17px;background:var(--accent);color:var(--accentText);box-shadow:0 8px 22px rgba(70,120,240,.22)}footer.image-mode #upload{opacity:.35;pointer-events:none}button:disabled{opacity:.45;cursor:default}";

        private static readonly string QuickScript = @"const $=s=>document.querySelector(s);function post(m){chrome.webview.postMessage(m)}function css(t){document.body.dataset.theme=t.light?'light':'dark';const r=document.documentElement.style;r.setProperty('--accent',t.accent);r.setProperty('--accentText',t.accentText);r.setProperty('--text',t.text);r.setProperty('--sub',t.subText);r.setProperty('--muted',t.mutedText);r.setProperty('--windowTop',t.windowTop);r.setProperty('--windowBottom',t.windowBottom)}function render(s){css(s.theme);$('#app').textContent=s.appName;$('#status').textContent=(s.busy?'\u6b63\u5728\u751f\u6210\u56de\u590d':'\u5feb\u901f\u63d0\u95ee')+' / '+s.provider+' / '+s.model+(s.memory?' / '+s.memory:'');$('#send').disabled=!!s.busy}function send(){const i=$('#input');const v=i.value.trim();if(!v)return;post({action:'send',text:v});i.value=''}window.zakoFocus=()=>$('#input').focus();$('#send').onclick=send;$('#input').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||(!e.shiftKey&&!e.altKey))){e.preventDefault();send()}if(e.key==='Escape')post({action:'hide'})});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>post({action:b.dataset.action}));let drag=false;$('#drag').addEventListener('pointerdown',e=>{if(e.target.closest('button,textarea'))return;drag=true;post({action:'dragStart',screenX:Math.round(e.screenX),screenY:Math.round(e.screenY)})});addEventListener('pointermove',e=>{if(drag)post({action:'dragMove',screenX:Math.round(e.screenX),screenY:Math.round(e.screenY)})});addEventListener('pointerup',()=>{if(drag){drag=false;post({action:'dragEnd'})}});chrome.webview.addEventListener('message',e=>{if(e.data.type==='quickState')render(e.data)});post({action:'ready'});";

        private static readonly string SidebarScript = @"const $=s=>document.querySelector(s);let mode='text';let state={};function post(m){chrome.webview.postMessage(m)}function esc(s){return String(s||'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}function css(t){document.body.dataset.theme=t.light?'light':'dark';const r=document.documentElement.style;r.setProperty('--accent',t.accent);r.setProperty('--accentText',t.accentText);r.setProperty('--text',t.text);r.setProperty('--sub',t.subText);r.setProperty('--muted',t.mutedText);r.setProperty('--windowTop',t.windowTop);r.setProperty('--windowBottom',t.windowBottom)}function fileUrl(p){return p?('file:///'+String(p).replace(/\\/g,'/')):''}function imageSrc(m){return m.imagePath?fileUrl(m.imagePath):(m.sourceUrl||m.dataUrl||'')}function messageHtml(m){const role=m.role==='user'?'user':'assistant';if(m.messageType==='image'){const src=imageSrc(m);return `<div class='msg ${role} image-card'><div>${esc(m.content)||'\u56fe\u7247\u751f\u6210\u5b8c\u6210'}</div>${src?`<img src='${esc(src)}'>`:`<div class='image-meta'>\u9884\u89c8\u5df2\u8fc7\u671f</div>`}<div class='image-meta'>${esc(m.imageModelId||'\u56fe\u7247\u6a21\u578b')} / ${esc(m.imageSize||'\u9ed8\u8ba4\u5c3a\u5bf8')}</div></div>`}if(m.messageType==='vision'){const src=fileUrl(m.attachmentPath);return `<div class='msg ${role} vision-card'><div>${esc(m.content)||'\u56fe\u6587\u6d88\u606f'}</div>${src?`<img src='${esc(src)}'>`:''}<div class='attach-meta'>\u89c6\u89c9\u8f93\u5165 / ${esc(m.attachmentName||'\u672c\u5730\u56fe\u7247')}</div></div>`}return `<div class='msg ${role}'>${esc(m.content)||'...'}</div>`}function setMode(next){mode=next;$('#modeText').classList.toggle('active',mode==='text');$('#modeImage').classList.toggle('active',mode==='image');document.querySelector('footer').classList.toggle('image-mode',mode==='image');$('#input').placeholder=mode==='image'?'\u63cf\u8ff0\u8981\u751f\u6210\u7684\u56fe\u7247':'\u8f93\u5165\u6d88\u606f\uff0cCtrl+Enter \u53d1\u9001';$('#upload').disabled=mode!=='text'||!!state.busy||!!state.imageBusy;$('#send').title=mode==='image'?'\u751f\u6210\u56fe\u7247':'\u53d1\u9001'}function renderAttachment(s){const box=$('#attachment');if(!s.pendingImageName){box.innerHTML='';return}box.innerHTML=`<div class='attach-chip'>" + UiIcons.Image.Replace("\r", "").Replace("\n", "") + @"<b>${esc(s.pendingImageName)}</b><span>\u5c06\u968f\u4e0b\u4e00\u6761\u6d88\u606f\u53d1\u9001</span><button id='removeAttachment' title='\u79fb\u9664'>" + UiIcons.Close.Replace("\r", "").Replace("\n", "") + @"</button></div>`;$('#removeAttachment').onclick=()=>post({action:'removeAttachment'})}function render(s){state=s;css(s.theme);$('#appName').textContent=s.appName;$('#status').textContent=(s.busy?'\u6b63\u5728\u751f\u6210\u56de\u590d':(s.imageBusy?'\u6b63\u5728\u751f\u6210\u56fe\u7247':'\u5df2\u5c31\u7eea'))+' / '+s.provider+' / '+s.model+(s.memory?' / '+s.memory:'');$('#toggleEdge').title=s.edge==='right'?'\u5207\u6362\u5230\u5de6\u4fa7':'\u5207\u6362\u5230\u53f3\u4fa7';$('#sessions').innerHTML=(s.sessions||[]).map(x=>`<div class='session ${x.id===s.selectedSessionId?'active':''}' data-id='${esc(x.id)}'><b>${esc(x.title)}</b><small>${esc(x.updatedAt)}</small><button class='del' data-id='${esc(x.id)}' title='\u5220\u9664'>" + UiIcons.Clear.Replace("\r", "").Replace("\n", "") + @"</button></div>`).join('');$('#messages').innerHTML=(s.messages||[]).length?(s.messages||[]).map(messageHtml).join(''):'<div class=\'empty\'>\u5f00\u59cb\u4e00\u6b21\u65b0\u7684 Zako \u5bf9\u8bdd</div>';renderAttachment(s);$('#send').disabled=mode==='image'?!!s.imageBusy:!!s.busy;setMode(mode);$('#messages').scrollTop=$('#messages').scrollHeight}function send(){const i=$('#input');const v=i.value.trim();if(!v)return;if(mode==='image')post({action:'generateImage',text:v});else post({action:'send',text:v});i.value=''}$('#send').onclick=send;$('#upload').onclick=()=>post({action:'uploadImage'});$('#settings').onclick=()=>post({action:'settings'});$('#quickClose').onclick=()=>post({action:'hide'});$('#toggleEdge').onclick=()=>post({action:'toggleEdge'});$('#newChat').onclick=()=>post({action:'newChat'});$('#modeText').onclick=()=>setMode('text');$('#modeImage').onclick=()=>setMode('image');$('#sessions').onclick=e=>{const del=e.target.closest('.del');if(del){e.stopPropagation();post({action:'deleteSession',id:del.dataset.id});return}const row=e.target.closest('.session');if(row)post({action:'selectSession',id:row.dataset.id})};$('#input').addEventListener('keydown',e=>{if(e.key==='Enter'&&e.ctrlKey){e.preventDefault();send()}if(e.key==='Escape')post({action:'hide'})});chrome.webview.addEventListener('message',e=>{if(e.data.type==='sidebarState')render(e.data)});setMode('text');post({action:'ready'});";
    }
}
